import os
import hashlib
import hmac
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32).hex())
app.config['STORAGE_ROOT'] = '/var/app/storage'
app.config['MAX_FILE_SIZE'] = 10 * 1024 * 1024

# Security: Rate limiting state
_rate_limits = {}

def constant_time_compare(a, b):
    """Constant-time string comparison to prevent timing attacks."""
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def generate_token(username, role):
    """Generate HMAC-based authentication token."""
    payload = f"{username}:{role}:{int(__import__('time').time()) + 3600}"
    sig = hmac.new(app.config['SECRET_KEY'].encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"

def verify_token(token):
    """Verify HMAC token and return claims."""
    if not token or ':' not in token:
        return None
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, provided_sig = parts
    expected_sig = hmac.new(app.config['SECRET_KEY'].encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not constant_time_compare(expected_sig, provided_sig):
        return None
    fields = payload.split(':')
    if len(fields) != 3:
        return None
    username, role, expires = fields
    import time
    if int(expires) < time.time():
        return None
    return {'username': username, 'role': role}

def require_auth(f):
    """Authentication decorator."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)
        token = auth_header[7:]
        claims = verify_token(token)
        if not claims:
            abort(401)
        request.user = claims
        return f(*args, **kwargs)
    return decorated

class PathValidator:
    """Validates file paths to prevent directory traversal.

    Security measures:
    - Rejects null bytes
    - Rejects path traversal sequences
    - Validates against storage root
    - Normalizes unicode to prevent homoglyph attacks
    """

    BLOCKED_SEQUENCES = ['..', '~', '$', '`', '|', ';', '&', '\x00']
    ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc', '.csv'}

    @classmethod
    def validate_path(cls, user_path, base_dir):
        """Validate and resolve a user-supplied path.

        Returns the safe absolute path or raises ValueError.
        """
        if not user_path or not isinstance(user_path, str):
            raise ValueError("Invalid path")

        # Step 1: Check for null bytes
        if '\x00' in user_path:
            raise ValueError("Null byte in path")

        # Step 2: Unicode NFC normalization FIRST for consistent handling
        normalized_path = unicodedata.normalize('NFC', user_path)

        # Step 3: Check for blocked sequences AFTER normalization
        for seq in cls.BLOCKED_SEQUENCES:
            if seq in normalized_path:
                raise ValueError(f"Blocked sequence: {seq}")

        # Step 4: Check path components
        parts = PurePosixPath(normalized_path).parts
        for part in parts:
            if part.startswith('.'):
                raise ValueError("Hidden file access denied")

        # Step 5: Resolve final path using normalized input
        final_path = os.path.normpath(os.path.join(base_dir, normalized_path))

        # Step 6: Verify it's within base directory
        real_base = os.path.realpath(base_dir)
        real_final = os.path.realpath(final_path)
        if not real_final.startswith(real_base + os.sep):
            raise ValueError("Path traversal detected")

        # Step 7: Check extension
        _, ext = os.path.splitext(real_final)
        if ext.lower() not in cls.ALLOWED_EXTENSIONS:
            raise ValueError(f"Extension not allowed: {ext}")

        return real_final


@app.route('/api/files/<path:filepath>', methods=['GET'])
@require_auth
def read_file(filepath):
    """Read a file from user's storage directory."""
    user = request.user['username']
    # Strict username validation
    if not user.isalnum():
        abort(403)
    user_dir = os.path.join(app.config['STORAGE_ROOT'], user)

    try:
        safe_path = PathValidator.validate_path(filepath, user_dir)
    except ValueError as e:
        abort(403, description=str(e))

    if not os.path.isfile(safe_path):
        abort(404)

    with open(safe_path, 'rb') as f:
        content = f.read(app.config['MAX_FILE_SIZE'])

    return content, 200, {'Content-Type': 'application/octet-stream'}


@app.route('/api/files/<path:filepath>', methods=['PUT'])
@require_auth
def write_file(filepath):
    """Write a file to user's storage directory."""
    user = request.user['username']
    if not user.isalnum():
        abort(403)
    user_dir = os.path.join(app.config['STORAGE_ROOT'], user)

    try:
        safe_path = PathValidator.validate_path(filepath, user_dir)
    except ValueError as e:
        abort(403, description=str(e))

    data = request.get_data()
    if len(data) > app.config['MAX_FILE_SIZE']:
        abort(413)

    os.makedirs(os.path.dirname(safe_path), exist_ok=True)
    with open(safe_path, 'wb') as f:
        f.write(data)

    return jsonify({'status': 'ok', 'path': filepath})


@app.route('/api/files', methods=['GET'])
@require_auth
def list_files():
    """List files in user's storage directory."""
    user = request.user['username']
    if not user.isalnum():
        abort(403)
    user_dir = os.path.join(app.config['STORAGE_ROOT'], user)

    if not os.path.isdir(user_dir):
        return jsonify({'files': []})

    files = []
    for root, dirs, filenames in os.walk(user_dir):
        # Don't traverse hidden directories
        dirs[:] = [d for d in dirs if not d.startswith('.')]
        for fname in filenames:
            if not fname.startswith('.'):
                rel = os.path.relpath(os.path.join(root, fname), user_dir)
                files.append(rel)

    return jsonify({'files': files})


@app.route('/api/admin/users', methods=['GET'])
@require_auth
def admin_list_users():
    """Admin endpoint to list all users."""
    if request.user['role'] != 'admin':
        abort(403)

    storage_root = app.config['STORAGE_ROOT']
    if not os.path.isdir(storage_root):
        return jsonify({'users': []})

    users = [d for d in os.listdir(storage_root) 
             if os.path.isdir(os.path.join(storage_root, d))]
    return jsonify({'users': users})


